public class WordSearch {
    char[][] board; int rows, cols;
    public boolean exist(char[][] board, String word) {
        this.board = board; rows = board.length; cols = board[0].length;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (dfs(r, c, word, 0)) return true;
        return false;
    }
    boolean dfs(int r, int c, String word, int idx) {
        if (idx == word.length()) return true;
        if (r<0||r>=rows||c<0||c>=cols||board[r][c]!=word.charAt(idx)) return false;
        char tmp = board[r][c];
        board[r][c] = '#'; // mark visited
        boolean found = dfs(r+1,c,word,idx+1)||dfs(r-1,c,word,idx+1)||
                        dfs(r,c+1,word,idx+1)||dfs(r,c-1,word,idx+1);
        board[r][c] = tmp; // backtrack
        return found;
    }
}

